D = (B + C)/2;
E = (C + A)/2;
F = (A + B)/2;
G = (A + B + C)/3;
P = (G + reflect(B,C)*(G))/2;
Q = (A + reflect(B,C)*(A))/2;

draw(A--B--C--cycle);
draw(A--D);
draw(B--E);
draw(C--F);
draw(G--P);
draw(A--Q);

label("$A$", A, dir(90));
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, SE);
label("$E$", E, NE);
label("$F$", F, NW);
label("$G$", G, NE);
label("$P$", P, S);
label("$Q$", Q, SSW);
[/asy]

